"""Original rheumatoid arthritis questions: recognition, classification and complications."""
from qbank_authoring import question,ref
rows=[]
C=ref('ACR/EULAR 2010 rheumatoid arthritis classification criteria','https://ard.bmj.com/content/69/9/1580')
E=ref('EULAR rheumatoid arthritis management: 2025 update, published 2026','https://doi.org/10.1016/j.ard.2026.01.023')
A=ref('ACR 2021 rheumatoid arthritis treatment guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC9273041/')
I=ref('ACR/CHEST guideline: screening and monitoring autoimmune rheumatic ILD','https://pmc.ncbi.nlm.nih.gov/articles/PMC12646464/')

def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A 42-year-old woman has 10 weeks of morning stiffness lasting 90 minutes, boggy swelling of both wrists and several MCP and PIP joints. DIP joints are spared. Which diagnosis best fits?', 'Rheumatoid arthritis',[
 ('Erosive hand osteoarthritis','This usually emphasizes DIP/PIP joints with bony enlargement and central erosions rather than this MCP/wrist synovitis pattern.'),('Psoriatic arthritis','Look for psoriasis, nail disease, dactylitis, enthesitis or a different distribution; the stated pattern favors RA.'),('Hemochromatosis arthropathy','Second/third MCP involvement can mimic RA, but hook osteophytes, chondrocalcinosis and iron overload provide discriminating clues.')],
 'Recognize persistent small-joint synovitis','**Symmetric MCP, PIP and wrist inflammation with prolonged stiffness is a characteristic RA presentation.**',['Tenderness alone does not establish synovitis: identify swelling, warmth or restricted movement.','Early disease can be asymmetric, and normal radiographs do not exclude it.'], '**Refer early and evaluate disease activity and mimics.**',['Check RF/ACPA and inflammatory markers without making positivity mandatory.','Persistent inflammation can cause structural damage before obvious deformity develops.'],[['MCP/wrist boggy swelling','Inflammatory synovitis'],['DIP bony enlargement','Osteoarthritis or another differential'],['Dactylitis/nail disease','Suggest psoriatic arthritis']],[C,A],style='clinical_scenario')

q('Before applying the 2010 ACR/EULAR rheumatoid arthritis classification score, which condition is required?', 'At least one clinically swollen joint with no better alternative explanation',[
 ('A positive rheumatoid factor regardless of joint findings','RF alone is neither sufficiently specific nor the entry requirement.'),('Definite erosions in both hands','Erosions are not required for the early classification pathway.'),('Symmetric involvement of at least five joints','Symmetry and this joint count are not entry requirements.')],
 'Classification begins with an eligible clinical population','**The score applies to clinical synovitis that is not better explained by another disorder.**',['Gout, infection, psoriatic arthritis and lupus may provide a better explanation.','Classification criteria standardize groups; they do not replace individualized diagnosis.'], '**Do not score an isolated positive antibody as definite RA.**',['A patient below the threshold can be followed and reassessed.','Urgent evaluation of a possible infected joint takes priority over classification.'],[['Entry','Unexplained clinical synovitis'],['Score','Joint, serology, inflammation and duration domains'],['Purpose','Classification supporting clinical assessment']],[C])

q('A patient with unexplained synovitis has 6 involved small joints, anti-CCP 5 times the laboratory upper limit, raised CRP and 8 weeks of symptoms. What is the 2010 ACR/EULAR score?', '8 out of 10',[
 ('6 out of 10','This undercounts the combination of small-joint and high-positive serology scores.'),('7 out of 10','This misses one of the elevated acute-phase or duration points.'),('10 out of 10','The maximum joint score requires more than 10 joints, including at least one small joint.')],
 'Calculate the four domains correctly','**The total is 3 + 3 + 1 + 1 = 8.**',['Four to ten small joints contribute three points; high-positive RF or ACPA contributes three.','Abnormal CRP/ESR and symptoms of at least six weeks each contribute one point.'], '**A score of at least six classifies definite RA in an eligible patient.**',['RF and ACPA points are not added together.','An alternative explanation for the synovitis still needs exclusion.'],[['Joint domain','3'],['Serology','3'],['Inflammation and duration','1 + 1']],[C],style='clinical_scenario')

q('Which interpretation of anti-citrullinated protein antibodies in rheumatoid arthritis is most accurate?', 'They support the diagnosis and predict erosive risk, but negative testing does not exclude RA',[
 ('They are required in every patient with RA','Seronegative RA is recognized.'),('They measure current disease activity sufficiently to replace joint examination','Antibody titers are not a substitute for clinical disease activity assessment.'),('They distinguish RA from every infectious and autoimmune mimic with absolute specificity','Specificity is high in an appropriate context but is not absolute.')],
 'Use serology as probability and prognosis','**ACPA is a useful disease-associated marker, rather than a stand-alone verdict.**',['Clinical phenotype and persistence of synovitis remain central.','Seropositivity, especially high levels, is associated with a more erosive course at the population level.'], '**Interpret the result with the pretest probability.**',['An unexpected positive result should prompt examination and thoughtful follow-up.','Do not withhold treatment assessment solely because both RF and ACPA are negative.'],[['Positive ACPA','Supports RA in the appropriate phenotype'],['Negative ACPA','Does not exclude RA'],['Disease activity','Requires clinical assessment']],[C,A])

q('A 65-year-old man with hepatitis C has a positive rheumatoid factor but no swollen joints. What is the best interpretation?', 'RF positivity alone does not establish rheumatoid arthritis',[
 ('RA is established and methotrexate should be started solely on this result','Treatment requires a compatible diagnosis, not isolated serology.'),('A positive RF excludes chronic infection as a contributor','RF can be present in chronic infections and other autoimmune conditions.'),('A normal CRP would prove that he can never develop inflammatory arthritis','A normal marker neither establishes the present diagnosis nor predicts all future disease.')],
 'Rheumatoid factor is not disease-specific','**RF may accompany chronic infections, other autoimmune disease and aging.**',['Its predictive value changes with clinical context and titer.','HCV-associated arthritis or cryoglobulinemia needs its own assessment if symptoms develop.'], '**Avoid treating a laboratory result as inflammatory joint disease.**',['Examine for true synovitis and ask about stiffness and function.','Use ACPA and additional investigations only when they answer a clinical question.'],[['RF positive without synovitis','Insufficient for RA'],['Compatible persistent synovitis','Investigate inflammatory arthritis'],['Chronic infection','Potential alternative source of RF']],[C],style='clinical_scenario')

q('What is the principal structural process responsible for marginal erosions in rheumatoid arthritis?', 'Inflamed synovial pannus with cytokine-driven osteoclast activation',[
 ('Central cartilage mineralization by calcium pyrophosphate crystals','CPP deposition explains chondrocalcinosis, not the principal RA erosion mechanism.'),('Avascular necrosis from isolated arterial occlusion in every affected joint','Osteonecrosis is a separate process and does not explain typical marginal erosions.'),('Urate deposition followed by punched-out erosions with overhanging edges','This describes chronic gout more closely.')],
 'Synovitis links immune activation to bone damage','**Persistent synovial inflammation promotes osteoclast-mediated marginal bone loss.**',['TNF, IL-6 and RANKL-linked pathways contribute to inflammation and damage.','Erosions arise near joint margins where bone is vulnerable to inflamed synovium.'], '**Disease modification aims to suppress inflammation before irreversible damage.**',['Analgesia alone does not reliably prevent erosions.','Compare new films with prior imaging when structural progression is uncertain.'],[['RA','Marginal erosions with synovitis'],['Gout','Tophi and overhanging erosions'],['CPPD','Cartilage calcification may be present']],[A])

q('A patient with suspected early RA has normal hand radiographs but persistent objective MCP swelling. Which statement is correct?', 'Normal radiographs do not exclude early inflammatory arthritis',[
 ('RA requires radiographic erosions before a DMARD can be considered','Waiting for damage forfeits the early treatment opportunity.'),('Normal films establish fibromyalgia as the cause of swelling','Fibromyalgia does not itself produce objective inflammatory synovitis.'),('MRI is mandatory before any clinical diagnosis can be made','Imaging may clarify uncertainty, but it is not universally mandatory.')],
 'Imaging can lag behind active disease','**Inflammation can precede visible erosions on plain radiographs.**',['Ultrasound can identify synovial hypertrophy, effusion and Doppler activity when the examination is uncertain.','Imaging findings must still be interpreted with clinical and serological information.'], '**Assess persistent clinical synovitis promptly.**',['Obtain baseline structural assessment as appropriate.','Do not delay referral solely while waiting for radiographic changes.'],[['Radiograph','Structural assessment'],['Ultrasound','Synovitis and Doppler signal'],['Clinical swelling','Important evidence even with normal films']],[C,A],style='clinical_scenario')

q('A patient with well-controlled RA develops an acutely hot swollen knee and fever while taking a biologic. What is the next diagnostic priority?', 'Urgent arthrocentesis for cell count, Gram stain, culture and crystals',[
 ('Increase prednisone immediately without sampling because all new swelling is a flare','Immunosuppression and RA increase concern for septic arthritis.'),('Use serum urate to exclude joint infection','Serum urate cannot exclude septic arthritis or confirm the cause of an acute effusion.'),('Wait for anti-CCP titers before deciding whether to aspirate','Antibody levels do not answer the urgent infection question.')],
 'Do not label every inflamed joint as an RA flare','**Septic arthritis must be actively excluded in an acutely inflamed joint.**',['Clinical findings and inflammatory markers overlap with crystal disease and autoimmune inflammation.','Finding crystals does not completely exclude concomitant infection.'], '**Sample promptly and treat suspected infection without avoidable delay.**',['Obtain blood cultures when systemic infection is suspected.','Coordinate drainage, antibiotics and immunosuppressive medication decisions according to severity.'],[['Synovial culture','Identifies infection when positive'],['Crystals','Can coexist with infection'],['RF/ACPA','Do not diagnose an acute septic joint']],[A],style='clinical_scenario')

q('A woman with longstanding erosive RA develops neck pain, hand clumsiness and brisk reflexes. Which complication is most urgent to evaluate?', 'Cervical instability with spinal cord compression',[
 ('Uncomplicated carpal tunnel syndrome as the sole explanation','Carpal tunnel can cause hand symptoms but does not account for upper motor neuron signs.'),('Isolated active wrist synovitis','Joint synovitis does not explain hyperreflexia and possible myelopathy.'),('A painless rheumatoid nodule causing cosmetic concern','This cannot explain the neurological syndrome.')],
 'Cervical disease can threaten the cord','**RA can damage cervical joints and stabilizing ligaments, including the atlantoaxial complex.**',['Neurological signs require urgent spinal assessment and appropriate imaging.','Avoid forceful neck manipulation when instability is possible.'], '**Protect the cervical spine and obtain specialist evaluation.**',['Communicate the risk before airway procedures.','MRI assesses cord compromise; dynamic studies are chosen only when safe and appropriate.'],[['Hand numbness alone','May reflect peripheral entrapment'],['Hyperreflexia and clumsy gait','Suggest myelopathy'],['RA plus neck symptoms','Consider instability']],[ref('Rheumatoid cervical spine disease: review','https://pmc.ncbi.nlm.nih.gov/articles/PMC4553335/')],style='clinical_scenario')

q('Longstanding seropositive RA is accompanied by persistent neutropenia, splenomegaly and recurrent bacterial infections. Which syndrome is most likely?', 'Felty syndrome',[
 ('Adult-onset Still disease','This classically has systemic inflammation with neutrophilic leukocytosis rather than this RA-neutropenia phenotype.'),('Isolated immune thrombocytopenia','This involves platelets and does not explain the stated neutropenia triad.'),('Drug-free benign ethnic neutropenia as an automatic diagnosis','The clinical setting and recurrent infection require investigation for disease-associated and other acquired causes.')],
 'Recognize RA-associated neutropenia','**Felty syndrome is associated with RA and neutropenia; splenomegaly is common.**',['Exclude medication toxicity, infection, nutritional causes and hematological disease.','T-cell large granular lymphocytic leukemia is an important overlapping differential requiring blood and clonality assessment when indicated.'], '**Treat infection promptly and investigate the cause of neutropenia.**',['Management of the underlying RA and selected G-CSF use depend on severity and recurrence.','Splenectomy is not an automatic first step for every patient.'],[['Felty','RA-associated neutropenia'],['T-LGL disorder','Clonal cytotoxic lymphocyte population'],['Medication toxicity','Review marrow-suppressing drugs']],[ref('Felty syndrome: mechanisms, differential diagnosis and treatment','https://pmc.ncbi.nlm.nih.gov/articles/PMC10619942/')],style='clinical_scenario')

q('A man with RA has progressive exertional dyspnea, basal inspiratory crackles and reduced diffusing capacity. Which investigation best characterizes suspected interstitial lung disease?', 'High-resolution chest CT together with pulmonary function assessment',[
 ('A normal chest radiograph alone to exclude ILD','Plain radiography is insufficiently sensitive for early interstitial disease.'),('Serial RF titers alone to stage pulmonary fibrosis','Serology cannot replace structural and functional lung assessment.'),('Routine surgical lung biopsy before any chest CT','Biopsy is not a universal first investigation for a typical clinical-radiological phenotype.')],
 'Combine structural and physiological assessment','**HRCT and pulmonary function tests provide complementary information in RA-associated ILD.**',['Exclude infection, heart failure, drug toxicity and pulmonary vascular disease as appropriate.','Risk assessment and monitoring intervals are individualized, often with rheumatology-pulmonology collaboration.'], '**Do not assume all RA-related dyspnea is a joint disease flare.**',['Compare FVC and DLCO trends and exertional oxygenation where indicated.','Treatment depends on inflammatory activity, fibrotic progression and comorbid disease.'],[['HRCT','Pattern and extent'],['PFTs','Functional impact and trend'],['Chest radiograph alone','Can miss clinically important ILD']],[I],style='clinical_scenario')

q('A patient with RA, new palpable purpura, foot drop and systemic symptoms has little active joint swelling. What is the most concerning explanation?', 'Rheumatoid vasculitis with mononeuritis multiplex',[
 ('Simple dependent edema','This does not account for purpura and an asymmetric motor neuropathy.'),('Uncomplicated fibromyalgia','Fibromyalgia does not cause objective focal neurological deficit or vasculitic purpura.'),('A mechanical lumbar strain explaining the entire syndrome','A strain cannot unify the skin and systemic findings.')],
 'Extra-articular severity need not parallel joint activity','**Vasculitic injury can produce cutaneous lesions and ischemic peripheral nerve deficits in established RA.**',['Exclude infection, embolic disease, ANCA-associated vasculitis and other causes.','Tissue confirmation from an appropriate involved site can guide treatment when feasible.'], '**Rapidly assess the distribution and severity of organ involvement.**',['Nerve conduction studies help document an asymmetric axonal neuropathy.','Organ-threatening disease needs specialist-directed immunosuppression after urgent evaluation for mimics.'],[['Purpura','Suggests small-vessel injury'],['Asymmetric foot drop','Possible mononeuritis multiplex'],['Quiet joints','Does not exclude systemic disease']],[ref('Rheumatoid vasculitis: clinical features and management','https://pmc.ncbi.nlm.nih.gov/articles/PMC2950222/')],style='clinical_scenario')

if __name__=='__main__':print(f'Rheumatoid arthritis diagnosis and complications: {len(rows)} questions')
